  INDEX `nip_penghapus`(`nip_penghapus` ASC) USING BTREE,
  INDEX `nip_pengganti`(`nip_pengganti` ASC) USING BTREE,
  INDEX `tgl_cppt`(`tgl_cppt` ASC) USING BTREE,
  INDEX `nip_pengganti_2`(`nip_pengganti` ASC) USING BTREE,
  CONSTRAINT `cppt_history_ibfk_2` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

