-- ----------------------------
-- Table structure for cppt_konfirmasi_terapi
-- ----------------------------
DROP TABLE IF EXISTS `cppt_konfirmasi_terapi`;
CREATE TABLE `cppt_konfirmasi_terapi`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tgl_cppt` date NULL DEFAULT NULL,
  `jam_cppt` time NULL DEFAULT NULL,
  `cppt_shift` enum('-','1','2','3') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `waktu_simpan` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tgl_lapor` date NULL DEFAULT NULL,
  `jam_lapor` time NULL DEFAULT NULL,
  `tgl_verifikasi` date NULL DEFAULT NULL,
  `jam_verifikasi` time NULL DEFAULT NULL,
  `nip_petugas_konfir` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nip_dpjp_konfir` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  PRIMARY KEY (`waktu_simpan`, `no_rawat`) USING BTREE,
  INDEX `no_rawat`(`no_rawat` ASC) USING BTREE,
  INDEX `nip_petugas_konfir`(`nip_petugas_konfir` ASC) USING BTREE,
  INDEX `nip_dpjp_konfir`(`nip_dpjp_konfir` ASC) USING BTREE,
  CONSTRAINT `cppt_konfirmasi_terapi_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `cppt_konfirmasi_terapi_ibfk_2` FOREIGN KEY (`nip_petugas_konfir`) REFERENCES `petugas` (`nip`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `cppt_konfirmasi_terapi_ibfk_3` FOREIGN KEY (`nip_dpjp_konfir`) REFERENCES `dokter` (`kd_dokter`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

