-- Table structure for hiv_follow_up_perawatan_dan_terapi
-- ----------------------------
DROP TABLE IF EXISTS `hiv_follow_up_perawatan_dan_terapi`;
CREATE TABLE `hiv_follow_up_perawatan_dan_terapi`  (
  `no_rkm_medis` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tgl_follow_up` date NULL DEFAULT NULL,
  `rencana_tgl_kunjungan` date NULL DEFAULT NULL,
  `bb` varchar(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tb` varchar(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `stts_fungsional` enum('','1. Kerja','2. Ambulatori','3. Baring') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `stad_who` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `hamil` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `metode_kb` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `infeksi_oportunistik` enum('','K','D','Cr','PCP','CMV','P','Z','S','T','H','Lain-lain') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `infeksi_oportunistik_lainya` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `obat_utk_io` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `status_tb` enum('','1. Tidak ada gejala/tanda TB','2. Suspek TB (rujuk ke klinik DOTS atau pemeriksaan sputum)','3. Dalam terapi TB') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ppk` enum('Y','T') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `obat_arv_dan_dosis_yg_diberikan` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `adherance_art` enum('','1. (>95%)','2. (80-95%)','3. (<80%)') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `efek_samping_art` enum('','R','Mua','Mun','D','N','Ikt','An','Ll','SK','Dem','Hip','Dep','P','Lip','Ngan','Ln') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `efek_samping_art_lain` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jumlah_cd4` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `hasil_lab` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `diberikan_kondom` enum('','Ya','Tidak','Tidak Ada') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `rujuk_ke_spesialis_atau_mrs` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tgl_simpan` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`tgl_simpan`) USING BTREE,
  INDEX `no_rkm_medis`(`no_rkm_medis` ASC) USING BTREE,
  CONSTRAINT `hiv_follow_up_perawatan_dan_terapi_ibfk_1` FOREIGN KEY (`no_rkm_medis`) REFERENCES `hiv_identitas_riwayat_pribadi` (`no_rkm_medis`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

