-- Table structure for hiv_identitas_riwayat_pribadi
-- ----------------------------
DROP TABLE IF EXISTS `hiv_identitas_riwayat_pribadi`;
CREATE TABLE `hiv_identitas_riwayat_pribadi`  (
  `no_rkm_medis` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `no_reg_nasional` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nm_pengawas_pmo` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `hubungan_dg_pasien` enum('','Saudara','Ayah','Ibu','Anak','Suami','Istri','Sepupu','Pasien Sendiri','Paman','Bibi','Kakek','Nenek','Teman','Tetangga','Ipar','Besan','Menantu','Mertua','Keponakan','Kakak','Adik','Pendukung','LSM') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `alamat_pmo` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `no_telpon_pmo` varchar(13) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_alergi_obat` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tgl_konfirmasi_tes_hiv` date NULL DEFAULT NULL,
  `entry_point` enum('','1. KIA','2. Rawat Jalan','3. Rawat Inap','4. Praktek Swasta','5. Jangkauan','6. LSM','7. Datang Sendiri','8. Lainnya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `delapan_lainnya_uraikan` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `rawat_jalan` enum('','TB','Anak','Penyakit Dalam','IMS','Lainnya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `lainnya_rawat_jalan` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jangkauan` enum('','IDU','PSK','LSL','Lainnya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `lainnya_jangkauan` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `dirujuk_msk_dari_klinik_lain` enum('','Tanpa ART','Dengan ART') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nm_klinik_sebelumnya` varchar(150) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tgl_rujuk_msk` date NULL DEFAULT NULL,
  `pendidikan` enum('0. Tidak Sekolah','1. SD','2. SMP','3. SMU','4. Perguruan Tinggi') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `stts_pekerjaan` enum('0. Tidak Bekerja','1. Bekerja') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `faktor_resiko` enum('1. Heteroseksual','2. Homoseksual','3. Biseksual','4. Perinatal','5. Transfusi Darah','6. NAPZA Suntik','7. Lain-lain') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `lain2_faktor_resiko_uraian` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kd_rejimen` varchar(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `dirujuk_masuk` enum('Tidak','Ya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `stts_pernikahan` enum('','Menikah','Belum Menikah','Janda/Duda') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `menerima_art` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `art_ya` enum('','1. PMTCT','2. ART','3. PPP') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tmpt_art_dulu` enum('','1. RS Pemerintah','2. RS Swasta','3. PKM') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  PRIMARY KEY (`no_rkm_medis`) USING BTREE,
  CONSTRAINT `hiv_identitas_riwayat_pribadi_ibfk_1` FOREIGN KEY (`no_rkm_medis`) REFERENCES `pasien` (`no_rkm_medis`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

