  `cek_sign_out` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `cek_selesai` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `sign_in` time NULL DEFAULT NULL,
  `time_out` time NULL DEFAULT NULL,
  `sign_out` time NULL DEFAULT NULL,
  `selesai` time NULL DEFAULT NULL,
  `catatan_deskripsi` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `instruksi_post_ops` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `jml_perdarahan` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `transfusi` enum('-','Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jns_transfusi` enum('-','WB','PRC') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jml_transfusi` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jaringan` enum('-','Ada','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jns_jaringan` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `pemeriksaan_pa` enum('-','Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `komplikasi` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tgl_laporan` date NULL DEFAULT NULL,
  `jam_laporan` time NULL DEFAULT NULL,
  `waktu_simpan` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`waktu_simpan`) USING BTREE,
  INDEX `nip_dr_operator`(`nip_dr_operator` ASC) USING BTREE,
  INDEX `nip_asisten`(`nip_asisten` ASC) USING BTREE,
  INDEX `nip_instrumen`(`nip_instrumen` ASC) USING BTREE,
  INDEX `nip_onloop`(`nip_onloop` ASC) USING BTREE,
  INDEX `nip_dr_anastesi`(`nip_dr_anastesi` ASC) USING BTREE,
  INDEX `nip_perawat_anastesi`(`nip_perawat_anastesi` ASC) USING BTREE,
  INDEX `no_rawat`(`no_rawat` ASC) USING BTREE,
  CONSTRAINT `laporan_operasi_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `laporan_operasi_ibfk_2` FOREIGN KEY (`nip_dr_operator`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `laporan_operasi_ibfk_3` FOREIGN KEY (`nip_asisten`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `laporan_operasi_ibfk_4` FOREIGN KEY (`nip_instrumen`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `laporan_operasi_ibfk_5` FOREIGN KEY (`nip_onloop`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `laporan_operasi_ibfk_6` FOREIGN KEY (`nip_dr_anastesi`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `laporan_operasi_ibfk_7` FOREIGN KEY (`nip_perawat_anastesi`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

