  INDEX `pekerjaanpj`(`pekerjaanpj` ASC) USING BTREE,
  INDEX `alamatpj`(`alamatpj` ASC) USING BTREE,
  INDEX `namakeluarga`(`namakeluarga` ASC) USING BTREE,
  INDEX `kelurahanpj`(`kelurahanpj` ASC) USING BTREE,
  INDEX `kecamatanpj`(`kecamatanpj` ASC) USING BTREE,
  INDEX `kabupatenpj`(`kabupatenpj` ASC) USING BTREE,
  INDEX `kd_kel_domisili_pasien`(`kd_kel_domisili_pasien` ASC) USING BTREE,
  INDEX `kd_kec_domisili_pasien`(`kd_kec_domisili_pasien` ASC) USING BTREE,
  INDEX `kd_kab_domisili_pasien`(`kd_kab_domisili_pasien` ASC) USING BTREE,
  INDEX `no_rkm_medis`(`no_rkm_medis` ASC) USING BTREE,
  CONSTRAINT `pasien_ibfk_1` FOREIGN KEY (`kd_pj`) REFERENCES `penjab` (`kd_pj`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pasien_ibfk_2` FOREIGN KEY (`kd_kel`) REFERENCES `kelurahan` (`kd_kel`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pasien_ibfk_3` FOREIGN KEY (`kd_kec`) REFERENCES `kecamatan` (`kd_kec`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pasien_ibfk_4` FOREIGN KEY (`kd_kab`) REFERENCES `kabupaten` (`kd_kab`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pasien_ibfk_5` FOREIGN KEY (`kd_kel_domisili_pasien`) REFERENCES `kelurahan` (`kd_kel`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pasien_ibfk_6` FOREIGN KEY (`kd_kec_domisili_pasien`) REFERENCES `kecamatan` (`kd_kec`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pasien_ibfk_7` FOREIGN KEY (`kd_kab_domisili_pasien`) REFERENCES `kabupaten` (`kd_kab`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

