-- ----------------------------
-- Table structure for pasien_bayi
-- ----------------------------
DROP TABLE IF EXISTS `pasien_bayi`;
CREATE TABLE `pasien_bayi`  (
  `no_rkm_medis` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `umur_ibu` varchar(8) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nama_ayah` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `umur_ayah` varchar(8) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `berat_badan` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `panjang_badan` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `lingkar_kepala` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `proses_lahir` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `anakke` char(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jam_lahir` time NOT NULL,
  `keterangan` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diagnosa` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `penyulit_kehamilan` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ketuban` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `lingkar_perut` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `lingkar_dada` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `penolong` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `no_skl` varchar(30) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kematian_perinatal` enum('-','Kelahiran mati','Mati neonatal < 7 hari') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `sebab_kematian` enum('Asphyxia','Trauma Lahir','BBLR','Tetanus Neonatum','Kelainan Congenital','ISPA','Diare','Lain-lain','-') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `asal_rujukan` enum('Rumah Sakit','Bidan','Non Medis','Puskesmas','Faskes lainnya','Non Rujukan') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `dirujuk` enum('Tidak','Ya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jenis_alamat` enum('Dalam Wilayah Kab. Banjar','Luar Wilayah','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `cara_lahir` enum('Spontan','Letak Sungsang','VE/Forcep','SC','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jenis_penolong` enum('Dokter Spesialis','Bidan','','-') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `apgus_skor_menit1` enum('0-3','4-7','8-10','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `apgus_skor_menit5` enum('0-3','4-7','8-10','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `apgus_skor_menit10` enum('0-3','4-7','8-10','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `asal_bayi` enum('Dalam RS','Luar RS','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `umur_kehamilan` enum('<=35','36-40','>=42','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `rawat_gabung_dg_ibu` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `IMD` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `KMC` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `berat_badan_benar` int NOT NULL,
  `no_rawat_ibu` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nip_pejabat` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `menit_1_appearance` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `menit_1_pulse` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `menit_1_grimace` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `menit_1_activity` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `menit_1_respiration` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `menit_5_appearance` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `menit_5_pulse` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `menit_5_grimace` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `menit_5_activity` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `menit_5_respiration` enum('1','2','0','') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  PRIMARY KEY (`no_rkm_medis`) USING BTREE,
  UNIQUE INDEX `no_skl`(`no_skl` ASC) USING BTREE,
  INDEX `umur_ibu`(`umur_ibu` ASC) USING BTREE,
  INDEX `umur_ayah`(`umur_ayah` ASC) USING BTREE,
  INDEX `berat_badan`(`berat_badan` ASC) USING BTREE,
  INDEX `panjang_badan`(`panjang_badan` ASC) USING BTREE,
  INDEX `lingkar_kepala`(`lingkar_kepala` ASC) USING BTREE,
  INDEX `proses_lahir`(`proses_lahir` ASC) USING BTREE,
  INDEX `anakke`(`anakke` ASC) USING BTREE,
  INDEX `jam_lahir`(`jam_lahir` ASC) USING BTREE,
  INDEX `keterangan`(`keterangan` ASC) USING BTREE,
  INDEX `penolong`(`penolong` ASC) USING BTREE,
  CONSTRAINT `pasien_bayi_ibfk_1` FOREIGN KEY (`no_rkm_medis`) REFERENCES `pasien` (`no_rkm_medis`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pasien_bayi_ibfk_2` FOREIGN KEY (`penolong`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

