-- ----------------------------
-- Table structure for pegawai
-- ----------------------------
DROP TABLE IF EXISTS `pegawai`;
CREATE TABLE `pegawai`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `nik` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nama` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '-',
  `jk` enum('Pria','Wanita') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'Pria',
  `jbtn` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `jnj_jabatan` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `departemen` char(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `bidang` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `stts_wp` char(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `stts_kerja` char(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `npwp` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `pendidikan` varchar(80) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `gapok` double NULL DEFAULT NULL,
  `tmp_lahir` varchar(150) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `tgl_lahir` date NULL DEFAULT NULL,
  `alamat` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `kota` varchar(150) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `mulai_kerja` date NULL DEFAULT NULL,
  `ms_kerja` enum('<1','PT','FT>1','-') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '<1',
  `indexins` char(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `bpd` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `rekening` varchar(25) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `stts_aktif` enum('AKTIF','CUTI','KELUAR','TENAGA LUAR','PENSIUN') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'AKTIF',
  `wajibmasuk` tinyint NULL DEFAULT NULL,
  `pengurang` double NULL DEFAULT NULL,
  `indek` tinyint NULL DEFAULT NULL,
  `mulai_kontrak` date NULL DEFAULT NULL,
  `cuti_diambil` int NULL DEFAULT NULL,
  `dankes` double NULL DEFAULT NULL,
  `no_ktp` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '-',
  `gol_pangkat` varchar(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tmt_pangkat` date NULL DEFAULT NULL,
  `ms_kerja_thn` varchar(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ms_kerja_bln` varchar(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nm_diklat` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `thn_diklat` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jml_jam` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jurusan_pnddkn` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `thn_lulus_sekolah` varchar(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `batas_umur_pensiun` varchar(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tgl_pensiun` date NULL DEFAULT NULL,
  `eselon` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `catatan_mutasi` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `cek_mk_awal` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tgl_mk_awal` date NULL DEFAULT NULL,
  `cek_mk_akhir` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tgl_mk_akhir` date NULL DEFAULT NULL,
  `no_surat` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `sumber_gaji` enum('APBD','BLUD','-') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '-',
  PRIMARY KEY (`id`, `nik`) USING BTREE,
  UNIQUE INDEX `nik_2`(`nik` ASC) USING BTREE,
  INDEX `departemen`(`departemen` ASC) USING BTREE,
  INDEX `bidang`(`bidang` ASC) USING BTREE,
  INDEX `stts_wp`(`stts_wp` ASC) USING BTREE,
  INDEX `stts_kerja`(`stts_kerja` ASC) USING BTREE,
  INDEX `pendidikan`(`pendidikan` ASC) USING BTREE,
  INDEX `indexins`(`indexins` ASC) USING BTREE,
  INDEX `jnj_jabatan`(`jnj_jabatan` ASC) USING BTREE,
  INDEX `bpd`(`bpd` ASC) USING BTREE,
  INDEX `nama`(`nama` ASC) USING BTREE,
  INDEX `jbtn`(`jbtn` ASC) USING BTREE,
  INDEX `npwp`(`npwp` ASC) USING BTREE,
  INDEX `dankes`(`dankes` ASC) USING BTREE,
  INDEX `cuti_diambil`(`cuti_diambil` ASC) USING BTREE,
  INDEX `mulai_kontrak`(`mulai_kontrak` ASC) USING BTREE,
  INDEX `stts_aktif`(`stts_aktif` ASC) USING BTREE,
  INDEX `tmp_lahir`(`tmp_lahir` ASC) USING BTREE,
  INDEX `alamat`(`alamat` ASC) USING BTREE,
  INDEX `mulai_kerja`(`mulai_kerja` ASC) USING BTREE,
  INDEX `gapok`(`gapok` ASC) USING BTREE,
  INDEX `kota`(`kota` ASC) USING BTREE,
  INDEX `pengurang`(`pengurang` ASC) USING BTREE,
  INDEX `indek`(`indek` ASC) USING BTREE,
  INDEX `jk`(`jk` ASC) USING BTREE,
  INDEX `ms_kerja`(`ms_kerja` ASC) USING BTREE,
  INDEX `tgl_lahir`(`tgl_lahir` ASC) USING BTREE,
  INDEX `rekening`(`rekening` ASC) USING BTREE,
  INDEX `wajibmasuk`(`wajibmasuk` ASC) USING BTREE,
  CONSTRAINT `pegawai_ibfk_3` FOREIGN KEY (`bidang`) REFERENCES `bidang` (`nama`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pegawai_ibfk_4` FOREIGN KEY (`stts_wp`) REFERENCES `stts_wp` (`stts`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pegawai_ibfk_5` FOREIGN KEY (`stts_kerja`) REFERENCES `stts_kerja` (`stts`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pegawai_ibfk_6` FOREIGN KEY (`pendidikan`) REFERENCES `pendidikan` (`tingkat`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `pegawai_ibfk_8` FOREIGN KEY (`bpd`) REFERENCES `bank` (`namabank`) ON DELETE RESTRICT ON UPDATE CASCADE,
