  `trf_kls1` double NULL DEFAULT NULL,
  `trf_kls2` double NULL DEFAULT NULL,
  `trf_kls3` double NULL DEFAULT NULL,
  `hak_kelas` varchar(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `naik_kelas` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `lm_rawat` varchar(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `persen_tambahan` double NULL DEFAULT NULL,
  `rumus_selisih_tarif` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `total_byr` double NULL DEFAULT NULL,
