DROP TABLE IF EXISTS `penilaian_medis_ralan_geriatri`;
CREATE TABLE `penilaian_medis_ralan_geriatri`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tanggal` datetime NOT NULL,
  `kd_dokter` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `anamnesis` enum('Autoanamnesis','Alloanamnesis') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `hubungan` varchar(30) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keluhan_utama` varchar(2000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `rps` varchar(2000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `rpd` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `rpo` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `alergi` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `tulang_belakang` enum('Tegap','Membungkuk','Kifosis','Skoliosis','Lordosis') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `td` varchar(8) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `nadi` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `suhu` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `rr` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `kondisi_umum` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `status_psikologis_gds` enum('Skor 1-4 Tidak Ada Depresi','Skor Antara 5-9 Menunjukkan Kemungkinan Besar Depresi','Skor 10 Atau Lebih Menunjukkan Depresi') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kondisi_sosial` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `status_kognitif_mmse` enum('24-30 : Tidak Ada Gangguan Kognitif','18-23 : Gangguan Kognitif Sedang','0-17 : Gangguan Kognitif Berat') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kepala` enum('Normal','Abnormal','Tidak Diperiksa') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keterangan_kepala` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `thoraks` enum('Normal','Abnormal','Tidak Diperiksa') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keterangan_thoraks` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `abdomen` enum('Normal','Abnormal','Tidak Diperiksa') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keterangan_abdomen` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ekstremitas` enum('Normal','Abnormal','Tidak Diperiksa') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keterangan_ekstremitas` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `Integument_kebersihan` enum('Normal','Abnormal') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `Integument_warna` enum('Normal','Pucat','Sianosis','Lain-lain') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `Integument_kelembaban` enum('Kering','Lembab') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `Integument_gangguan_kulit` enum('Normal','Rash','Luka','Memar','Ptekie','Bula') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `status_fungsional` enum('20 : Mandiri (A)','12-19 : Ketergantungan Ringan (B)','9-11 : Ketergantungan Sedang (B)','5-8 : Ketergantungan Berat (C)','0-4 : Ketergantungan Total (C)') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `skrining_jatuh` enum('Risiko Rendah Skor 0-5','Risiko Sedang Skor 6-16','Risiko Tinggi Skor 17-30') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `status_nutrisi` enum('Skor 12-14 : Status Gizi Normal','Skor 8-11 : Berisiko Malnutrisi','Skor 0-7 : Malnutrisi') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `lainnya` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `lab` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `rad` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `pemeriksaan` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diagnosis` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diagnosis2` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `permasalahan` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `terapi` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tindakan` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `edukasi` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`no_rawat`) USING BTREE,
  INDEX `kd_dokter`(`kd_dokter` ASC) USING BTREE,
  CONSTRAINT `penilaian_medis_ralan_geriatri_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `penilaian_medis_ralan_geriatri_ibfk_2` FOREIGN KEY (`kd_dokter`) REFERENCES `dokter` (`kd_dokter`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

