CREATE TABLE `penilaian_resiko_jatuh_kebidanan`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kode_resiko` varchar(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`no_rawat`, `kode_resiko`) USING BTREE,
  INDEX `kode_resiko`(`kode_resiko` ASC) USING BTREE,
  CONSTRAINT `penilaian_resiko_jatuh_kebidanan_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `penilaian_resiko_jatuh_kebidanan_ibfk_2` FOREIGN KEY (`kode_resiko`) REFERENCES `master_faktor_resiko_igd` (`kode_resiko`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

