  `tgl_kontrol2` date NULL DEFAULT NULL,
  `jam_kontrol1` time NULL DEFAULT NULL,
  `jam_kontrol2` time NULL DEFAULT NULL,
  `tempat1` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tempat2` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `terapi_pulang` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `catatan` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `tgl_surat` date NULL DEFAULT NULL,
  `nip_dpjp` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nm_keluarga_pasien` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `waktu_simpan` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_file_nm_keluarga_pasien` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`no_rawat`) USING BTREE,
  INDEX `nip_dpjp`(`nip_dpjp` ASC) USING BTREE,
