  CONSTRAINT `periksa_lab_rujukan_ibfk_2` FOREIGN KEY (`no_lab`) REFERENCES `pendaftaran_lab_rujukan` (`no_lab`) ON DELETE RESTRICT ON UPDATE CASCADE
