  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jns_rekon` enum('-','Masuk RS','Transfer Antar Ruangan','Pulang') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `riwayat_alergi` enum('-','Tidak','Ya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ket_riwayat_alergi` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `membawa_obat_dari_luar` enum('-','Tidak','Ya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `catatan_obat_igd` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `catatan_obat_ranap` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `ketidaksesuaian` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `saran` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `keputusan` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `nip_pereview` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `nip_apoteker` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `tanggal` date NULL DEFAULT NULL,
  `waktu_simpan` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `catatan_obat_riwayat` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  PRIMARY KEY (`no_rawat`, `jns_rekon`) USING BTREE,
  INDEX `nip_pereview`(`nip_pereview` ASC) USING BTREE,
  INDEX `nip_apoteker`(`nip_apoteker` ASC) USING BTREE,
  CONSTRAINT `rekonsiliasi_obat_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `rekonsiliasi_obat_ibfk_2` FOREIGN KEY (`nip_pereview`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `rekonsiliasi_obat_ibfk_3` FOREIGN KEY (`nip_apoteker`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

