  `rute` varchar(140) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `dosis` varchar(140) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `aturan_pakai` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nip_dokter` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `waktu_simpan` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `cek_stop` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tgl_stop` date NULL DEFAULT NULL,
  `kategori_obat` enum('-','Dalam Perawatan','Pulang') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nm_obat` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`waktu_simpan`) USING BTREE,
  INDEX `no_rawat`(`no_rawat` ASC) USING BTREE,
