  CONSTRAINT `rekonsiliasi_obat_ranap_ibfk_2` FOREIGN KEY (`nip_dokter`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

