  `tgl_surat_dari` date NULL DEFAULT NULL,
  `pemeriksaan_dinyatakan` enum('','Baik kesehatannya','Kurang baik kesehatannya, besar harapan dapat diperbaiki','Tidak baik kesehatannya, dengan diagnosa','Lainnya','Baik kesehatannya, Tidak bertindik, dan Tidak bertato','Baik kesehatannya, dapat melangsungkan pernikahan','Tidak baik kesehatannya untuk melangsungkan pernikahan','Baik kesehatannya, tidak menyandang disabilitas') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keperluan` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `lama_berlaku` int NULL DEFAULT NULL,
  `satuan_lama` enum('hari','bulan','tahun') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `bb` varchar(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tb` varchar(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `gol_darah` varchar(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nip_dokter` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tmpt_lahir` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `hasil_pemeriksaan` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `diagnosa` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `nm_pasien` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `no_dokumen` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `caten` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `td` varchar(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nadi` varchar(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `bmi` varchar(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `disabilitas` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nomor_surat` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`no_rawat`, `no_surat`) USING BTREE,
  INDEX `FK_surat_keterangan_dokter_dokter`(`nip_dokter` ASC) USING BTREE,
  INDEX `no_surat`(`no_surat` ASC) USING BTREE,
