-- ----------------------------
DROP TABLE IF EXISTS `surat_keterangan_dokter_disabilitas`;
CREATE TABLE `surat_keterangan_dokter_disabilitas`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `no_surat` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `disabilitas_fisik` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `disabilitas_sensorik` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `disabilitas_intelektual` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `disabilitas_mental` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `fisik` enum('-','Amputasi','Kelemahan atau kekakuan anggota gerak atas dan bawah','Paraplegi (anggota tubuh bagian bawah yang meliputi kedua tungkai dan organ panggul)','Celebral Palsy (CP)','CTEV (Congenital Talipes Equinovarus)') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tangan_kaki` enum('-','Tangan Kanan','Tangan Kiri','Kaki Kanan','Kaki Kiri') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `sensorik` enum('-','Netral (Buta Total)','Netral (Persepsi Cahaya / Low Vision)','Rungu','Wicara','Rungu dan Wicara') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `intelektual` enum('-','Disabilitas Grahita','Disabilitas Syndrome') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `mental` enum('-','Psikososial (Skizofrenia)','Psikososial (Bipolar)','Psikososial (Depresi)','Psikososial (Anxietas)','Psikososial (Gangguan Kepribadian)','Disabilitas (Autis)','Disabilitas (Hiperaktif)') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `derajat_disabilitas1` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `derajat_disabilitas2` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `derajat_disabilitas3` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `derajat_disabilitas4` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `derajat_disabilitas5` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `derajat_disabilitas6` enum('ya','tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kemampuan_mobilitas1` enum('-','Jalan','Jalan perlahan','Jalan dengan alat bantu','Tidak mampu jalan') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kemampuan_mobilitas2` enum('-','Naik tangga','Tidak naik tangga perlahan','Tidak mampu naik tangga') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `gangguan_ekstremitas_atas` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ekstremitas_atas_kanan` enum('-','Kekuatan 0','Kekuatan 1','Kekuatan 2','Kekuatan 3','Kekuatan 4','Kekuatan 5') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ekstremitas_atas_kiri` enum('-','Kekuatan 0','Kekuatan 1','Kekuatan 2','Kekuatan 3','Kekuatan 4','Kekuatan 5') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `gangguan_ekstremitas_bawah` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ekstremitas_bawah_kanan` enum('-','Kekuatan 0','Kekuatan 1','Kekuatan 2','Kekuatan 3','Kekuatan 4','Kekuatan 5') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ekstremitas_bawah_kiri` enum('-','Kekuatan 0','Kekuatan 1','Kekuatan 2','Kekuatan 3','Kekuatan 4','Kekuatan 5') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `alat_bantu` enum('Tidak','Ada') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ket_alat_bantu` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `penyebab` enum('-','Sejak lahir','Kecelakaan dalam pekerjaan','Kecelakaan lalu lintas','Penyakit','Akibat stroke','Akibat kusta','Lain - lain') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tahun_penyebab` varchar(4) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `penyakit_lain` enum('Tidak','Ada') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ket_penyakit_lain` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `pengobatan` enum('Tidak','Ada') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ket_pengobatan` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `catatan` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `nomor_surat` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`no_rawat`, `no_surat`) USING BTREE,
  INDEX `no_surat`(`no_surat` ASC) USING BTREE,
  CONSTRAINT `surat_keterangan_dokter_disabilitas_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

