DROP TABLE IF EXISTS `surat_tindakan_kedokteran`;
CREATE TABLE `surat_tindakan_kedokteran`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
