  `alamat_penjab` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kd_kel` int NULL DEFAULT NULL,
  `kd_kec` int NULL DEFAULT NULL,
  `kd_kab` int NULL DEFAULT NULL,
  `hubungan_dg_pasien` enum('Pasien Sendiri','Ayah','Ibu','Anak','Suami','Istri','Sepupu','Saudara','Paman','Bibi','Kakek','Nenek','Teman','Tetangga','Ipar','Besan','Menantu','Mertua','Keponakan','Kakak','Adik','Cucu') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jns_surat` enum('PERSETUJUAN','PENOLAKAN','PENUNDAAN') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kasus_tindakan` enum('Ranap','Ralan') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nm_tindakan_kedokteran` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `alasan_penolakan` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nip_dokter_pelaksana` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `nip_pemberi_info` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `penerima_info` varchar(150) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `isi_info_diagnosis_kerja` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_dasar_diagnosis` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_tindakan` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_indikasi` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_tatacara` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_tujuan` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_resiko` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_komplikasi` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_prognosis` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_alternatif` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `isi_info_lainlain` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `waktu_simpan` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tgl_persetujuan` date NULL DEFAULT NULL,
  `jam_persetujuan` time NULL DEFAULT NULL,
  `tgl_penolakan` date NULL DEFAULT NULL,
  `jam_penolakan` time NULL DEFAULT NULL,
  `nm_pihak_klg` varchar(150) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nm_pihak_rs` varchar(150) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `id_file_nm_penjab` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `id_file_penerima_info` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `id_file_nm_pihak_klg` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `id_file_nm_pihak_rs` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `tgl_penundaan` date NULL DEFAULT NULL,
  `jam_penundaan` time NULL DEFAULT NULL,
  `alasan_penundaan` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  PRIMARY KEY (`waktu_simpan`, `no_rawat`) USING BTREE,
  INDEX `nip_dokter_pelaksana`(`nip_dokter_pelaksana` ASC) USING BTREE,
  INDEX `nip_pemberi_info`(`nip_pemberi_info` ASC) USING BTREE,
  INDEX `no_rawat`(`no_rawat` ASC) USING BTREE,
  CONSTRAINT `surat_tindakan_kedokteran_ibfk_1` FOREIGN KEY (`nip_dokter_pelaksana`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `surat_tindakan_kedokteran_ibfk_2` FOREIGN KEY (`nip_pemberi_info`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `surat_tindakan_kedokteran_ibfk_3` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

