-- ----------------------------
-- Table structure for transaksi_panjar
-- ----------------------------
DROP TABLE IF EXISTS `transaksi_panjar`;
CREATE TABLE `transaksi_panjar`  (
  `no_panjar` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tgl_panjar` date NULL DEFAULT NULL,
  `ruang_rawat` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `telp_1` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `telp_2` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nominal_panjar` double NULL DEFAULT NULL,
  `status_panjar` enum('-','Selesai','Kurang Bayar','Lebih Bayar','Lanjut Piutang') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nominal_balik` double NULL DEFAULT NULL,
  `nip_petugas_simpan` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `waktu_simpan` datetime NULL DEFAULT NULL,
  `nip_petugas_ganti` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `waktu_ganti` datetime NULL DEFAULT NULL,
  `keterangan` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `telah_terima` varchar(150) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `jumlah_tagihan` double NULL DEFAULT NULL,
  `selisih_tarif_bpjs` double NULL DEFAULT NULL,
  PRIMARY KEY (`no_panjar`) USING BTREE,
  INDEX `no_rawat`(`no_rawat` ASC) USING BTREE,
  INDEX `nip_petugas_simpan`(`nip_petugas_simpan` ASC) USING BTREE,
  INDEX `nip_petugas_ganti`(`nip_petugas_ganti` ASC) USING BTREE,
  CONSTRAINT `transaksi_panjar_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `transaksi_panjar_ibfk_2` FOREIGN KEY (`nip_petugas_simpan`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `transaksi_panjar_ibfk_3` FOREIGN KEY (`nip_petugas_ganti`) REFERENCES `pegawai` (`nik`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = COMPACT;

